function useLocalList(key: string) {
  const [items, setItems] = useState<number[]>(() => {
    if (typeof window === "undefined") return [];
    try {
      const stored = JSON.parse(window.localStorage.getItem(key) || "[]");
      return Array.isArray(stored) ? stored.filter((value): value is number => Number.isInteger(value)) : [];
    } catch { return []; }
  });
  const toggle = (id: number) => setItems((current) => {
    const next = current.includes(id) ? current.filter((x) => x !== id) : [...current, id];
    try { window.localStorage.setItem(key, JSON.stringify(next)); } catch { /* Storage may be disabled; keep the in-memory state usable. */ }
    return next;
  });
  return [items, toggle] as const;
}

type CardNote = { id: string; text: string; createdAt: number; updatedAt: number; read: boolean };

function readStoredNotes(): Record<string, CardNote[]> {
  if (typeof window === "undefined") return {};
  try {
    const parsed: unknown = JSON.parse(window.localStorage.getItem("prompt-gallery-notes") || "{}");
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) return {};
    return Object.fromEntries(Object.entries(parsed).map(([key, value]) => [key, Array.isArray(value) ? value.filter((item): item is Record<string, unknown> => Boolean(item) && typeof item === "object" && typeof (item as Record<string, unknown>).text === "string").map((item, index) => {
      const createdAt = typeof item.createdAt === "number" ? item.createdAt : Date.now() - index;
      return { id: typeof item.id === "string" ? item.id : `${key}-${createdAt}-${index}`, text: item.text as string, createdAt, updatedAt: typeof item.updatedAt === "number" ? item.updatedAt : createdAt, read: item.read === true };
    }) : []])) as Record<string, CardNote[]>;
  } catch {
    return {};
  }
}

type CardNotesProps = {
  notes: CardNote[];
  draft: string;
  editingId: string | null;
  onDraftChange: (value: string) => void;
  onSubmit: () => void;
  onEdit: (note: CardNote) => void;
  onDelete: (id: string) => void;
  onCancel: () => void;
};

function CardNotes({ notes, draft, editingId, onDraftChange, onSubmit, onEdit, onDelete, onCancel }: CardNotesProps) {
  return <div className="mt-6 rounded-2xl border border-[#2d2932]/10 bg-[#fffdf8] p-4"><div className="mb-3 flex items-center justify-between gap-3"><div><div className="flex items-center gap-2 font-display text-xl font-bold"><MessageCircle size={18} className="text-[#ff6b6b]" /> Your review notes</div><p className="mt-1 text-xs text-[#8a8187]">Does this prompt have any faults? Save your note and update or delete it later.</p></div><span className="rounded-full bg-white px-2.5 py-1 font-mono text-[10px] text-[#746c73]">{notes.length} note{notes.length === 1 ? "" : "s"}</span></div>{notes.length > 0 ? <div className="mb-3 max-h-64 space-y-2 overflow-y-auto">{notes.map((note) => <div key={note.id} className="rounded-xl border border-[#2d2932]/10 bg-white p-3"><div className="flex items-start justify-between gap-3"><p className="whitespace-pre-wrap text-sm leading-relaxed text-[#4d474e]">{note.text}</p><div className="flex shrink-0 items-center gap-1"><button onClick={() => onEdit(note)} className="rounded-full p-1.5 text-[#746c73] hover:bg-[#f4e9e5] hover:text-[#28252a]" aria-label="Edit note"><Pencil size={14} /></button><button onClick={() => onDelete(note.id)} className="rounded-full p-1.5 text-[#746c73] hover:bg-[#ffe1df] hover:text-[#d14f55]" aria-label="Delete note"><Trash2 size={14} /></button></div></div><p className="mt-2 font-mono text-[9px] uppercase tracking-wider text-[#a39aa0]">{note.updatedAt !== note.createdAt ? "Updated" : "Saved"} · {new Date(note.updatedAt).toLocaleString()}</p></div>)}</div> : <p className="mb-3 text-xs text-[#8a8187]">No notes yet. Record a fault, improvement idea, or test result for this prompt.</p>}<div className="flex flex-col gap-2 sm:flex-row"><input value={draft} onChange={(e) => onDraftChange(e.target.value)} onKeyDown={(e) => e.key === "Enter" && onSubmit()} placeholder="Does this prompt have any faults? Write your note..." className="min-w-0 flex-1 rounded-xl border border-[#2d2932]/15 bg-white px-3 py-2.5 text-sm outline-none focus:border-[#ff6b6b]" /><button onClick={onSubmit} className="rounded-xl bg-[#28252a] px-4 py-2.5 text-xs font-bold text-white">{editingId ? "Update note" : "Save note"}</button>{editingId && <button onClick={onCancel} className="rounded-xl border border-[#2d2932]/15 bg-white px-4 py-2.5 text-xs font-bold">Cancel</button>}</div></div>;
}

export default function Home() {
  const [query, setQuery] = useState("");
  const [categoryQuery, setCategoryQuery] = useState("");
  const [visibleCategoryCount, setVisibleCategoryCount] = useState(24);
  const [activeCategory, setActiveCategory] = useState("All prompts");
  const [selected, setSelected] = useState<(typeof prompts)[number] | null>(null);
  const [selectedCategory, setSelectedCategory] = useState<(typeof categoryCards)[number] | null>(null);
  const [categoryCopied, setCategoryCopied] = useState(false);
  const [selectedFileId, setSelectedFileId] = useState<string | null>(null);
  const [fileContents, setFileContents] = useState<Record<string, string>>({});
  const [fileCopied, setFileCopied] = useState(false);
  const [saved, toggleSaved] = useLocalList("prompt-gallery-saved");
  const [comment, setComment] = useState("");
  const [editingNoteId, setEditingNoteId] = useState<string | null>(null);
  const [notificationsOpen, setNotificationsOpen] = useState(false);
  useEffect(() => {
    if (!selectedFileId || fileContents[selectedFileId] || !promptFilePaths[selectedFileId]) return;
    fetch(promptFilePaths[selectedFileId])
      .then((response) => response.ok ? response.text() : Promise.reject(new Error("Source file unavailable")))
      .then((content) => setFileContents((current) => ({ ...current, [selectedFileId]: content })))
      .catch(() => toast.error("Source file unavailable", { description: "Please try opening the file again." }));
  }, [selectedFileId, fileContents]);
  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setSelected(null);
        setSelectedFileId(null);
        setSelectedCategory(null);
      }
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, []);
  const [comments, setComments] = useState<Record<string, CardNote[]>>(readStoredNotes);
  const activeCardKey = selected ? `prompt-${selected.id}` : selectedCategory ? `category-${selectedCategory.id}` : null;
  useEffect(() => { setComment(""); setEditingNoteId(null); }, [activeCardKey]);
  const activeNotes = activeCardKey ? comments[activeCardKey] || [] : [];
  const notificationNotes = useMemo(() => Object.entries(comments).flatMap(([cardKey, notes]) => notes.map((note) => ({ ...note, cardKey }))).sort((a, b) => b.createdAt - a.createdAt), [comments]);
  const unreadCount = notificationNotes.filter((note) => !note.read).length;
  const cardTitle = (cardKey: string) => { const [type, rawId] = cardKey.split("-"); const id = Number(rawId); return type === "prompt" ? prompts.find((p) => p.id === id)?.title || "Prompt card" : categoryCards.find((c) => c.id === id)?.title || "Category card"; };
  const persistNotes = (next: Record<string, CardNote[]>) => { setComments(next); try { window.localStorage.setItem("prompt-gallery-notes", JSON.stringify(next)); } catch { /* Keep notes available for this session if storage is restricted. */ } };
  const markAllNotificationsRead = () => { const next = Object.fromEntries(Object.entries(comments).map(([key, notes]) => [key, notes.map((note) => ({ ...note, read: true }))])) as Record<string, CardNote[]>; persistNotes(next); setNotificationsOpen(true); };
  const addOrUpdateNote = () => { if (!activeCardKey || !comment.trim()) return; const now = Date.now(); const existing = activeNotes; const nextNotes = editingNoteId ? existing.map((note) => note.id === editingNoteId ? { ...note, text: comment.trim(), updatedAt: now, read: true } : note) : [...existing, { id: `${now}-${Math.random().toString(36).slice(2, 8)}`, text: comment.trim(), createdAt: now, updatedAt: now, read: false }]; persistNotes({ ...comments, [activeCardKey]: nextNotes }); setComment(""); setEditingNoteId(null); toast.success(editingNoteId ? "Note updated on this device" : "Note saved on this device"); };
  const editNote = (note: CardNote) => { setComment(note.text); setEditingNoteId(note.id); };
  const deleteNote = (id: string) => { if (!activeCardKey) return; persistNotes({ ...comments, [activeCardKey]: activeNotes.filter((note) => note.id !== id) }); if (editingNoteId === id) { setEditingNoteId(null); setComment(""); } toast.success("Note deleted on this device"); };
  const cancelEditNote = () => { setEditingNoteId(null); setComment(""); };

  const filteredCategories = useMemo(() => categoryCards.filter((category) => `${category.title} ${category.description} ${category.kind}`.toLowerCase().includes(categoryQuery.toLowerCase())), [categoryQuery]);
  const visibleCategories = filteredCategories.slice(0, visibleCategoryCount);
  const filtered = useMemo(() => prompts.filter((p) => {
    const matchesCategory = activeCategory === "All prompts" || p.category === activeCategory;
    const haystack = `${p.title} ${p.category} ${p.type} ${p.excerpt} ${p.tags.join(" ")}`.toLowerCase();
    return matchesCategory && haystack.includes(query.toLowerCase());
  }), [query, activeCategory]);

  const copy = async (text: string) => {
    try {
      if (!navigator.clipboard) throw new Error("Clipboard API unavailable");
      await navigator.clipboard.writeText(text);
      toast.success("Prompt copied to clipboard", { description: "Your next scene starts here." });
    } catch {
      toast.error("Copy unavailable", { description: "Select the prompt text and copy it manually." });
    }
  };
  const selectedFile = selectedFileId ? promptFiles.find((file) => file.id === selectedFileId) : null;
  const copyFullFile = async () => { if (!selectedFileId || !fileContents[selectedFileId]) return; try { if (!navigator.clipboard) throw new Error("Clipboard API unavailable"); await navigator.clipboard.writeText(fileContents[selectedFileId]); setFileCopied(true); toast.success("Complete file copied", { description: "Every word from the source file is now on your clipboard." }); window.setTimeout(() => setFileCopied(false), 1800); } catch { toast.error("Copy unavailable", { description: "Select the source text and copy it manually." }); } };
  const copyCategoryPrompt = async () => { if (!selectedCategory) return; try { if (!navigator.clipboard) throw new Error("Clipboard API unavailable"); await navigator.clipboard.writeText(selectedCategory.prompt); setCategoryCopied(true); toast.success("Category prompt copied", { description: `${selectedCategory.title} is ready to use.` }); window.setTimeout(() => setCategoryCopied(false), 1800); } catch { toast.error("Copy unavailable", { description: "Select the prompt text and copy it manually." }); } };
  

  return <div className="min-h-screen bg-[#fbf7ef] text-[#28252a]">
    <header className="sticky top-0 z-30 border-b border-[#2d2932]/10 bg-[#fbf7ef]/90 backdrop-blur-xl">
      <div className="mx-auto flex max-w-[1440px] items-center justify-between px-5 py-4 lg:px-10">
        <button className="flex items-center gap-3" onClick={() => { setActiveCategory("All prompts"); window.scrollTo({ top: 0, behavior: "smooth" }); }} aria-label="Go to home">
          <span className="grid h-10 w-10 place-items-center overflow-hidden rounded-[14px] bg-[#ff6b6b] shadow-[4px_4px_0_#28252a]"><img src={images.mark} alt="Prompt Gallery mark" className="h-full w-full object-contain p-1.5" /></span>
          <span className="text-left"><span className="block font-display text-xl font-bold leading-none">Prompt Gallery</span><span className="mt-1 block font-mono text-[9px] uppercase tracking-[0.2em] text-[#746c73]">Creative video library</span></span>
        </button>
        <nav className="hidden items-center gap-8 text-sm font-semibold md:flex"><a href="#library" className="transition-colors hover:text-[#ff6b6b]">Explore</a><a href="#how" className="transition-colors hover:text-[#ff6b6b]">How it works</a><button onClick={() => toast("Creator collection", { description: "Save your favorite prompts to browse them here soon." })} className="transition-colors hover:text-[#ff6b6b]">My collection <span className="ml-1 rounded-full bg-[#28252a] px-2 py-0.5 text-xs text-white">{saved.length}</span></button></nav>
        <div className="relative flex items-center gap-2"><button onClick={() => { const willOpen = !notificationsOpen; setNotificationsOpen(willOpen); if (willOpen) markAllNotificationsRead(); }} className="relative rounded-full bg-white p-2.5 text-[#28252a] shadow-sm ring-1 ring-[#2d2932]/10 transition hover:-translate-y-0.5" aria-label={unreadCount ? `${unreadCount} unread notes` : "Notifications"}><Bell size={17} />{unreadCount > 0 && <span className="absolute -right-2 -top-2 min-w-5 rounded-full bg-[#ff6b6b] px-1.5 py-1 text-center font-mono text-[10px] font-bold text-white shadow-[2px_2px_0_#28252a]">{unreadCount > 999 ? "999+" : unreadCount}</span>}</button><button onClick={() => toast("Prompt Studio", { description: "The interactive master prompt is coming next." })} className="hidden items-center gap-2 rounded-full bg-[#28252a] px-4 py-2.5 text-sm font-bold text-white transition hover:-translate-y-0.5 sm:flex"><Wand2 size={15} /> Open Studio</button>{notificationsOpen && <div className="absolute right-0 top-14 z-50 w-[min(92vw,380px)] overflow-hidden rounded-2xl border border-[#2d2932]/10 bg-[#fbf7ef] shadow-2xl"><div className="flex items-center justify-between border-b border-[#2d2932]/10 px-4 py-3"><div><p className="font-display text-lg font-bold">Note notifications</p><p className="font-mono text-[9px] uppercase tracking-wider text-[#746c73]">Viewed notes are marked read</p></div><button onClick={markAllNotificationsRead} className="text-xs font-bold text-[#ff6b6b] hover:underline">Mark all read</button></div><div className="max-h-80 overflow-y-auto p-3">{notificationNotes.length ? notificationNotes.map((note) => <div key={note.id} className={`mb-2 rounded-xl p-3 ${note.read ? "bg-white" : "bg-[#ffe1df]"}`}><p className="font-mono text-[9px] font-bold uppercase tracking-wider text-[#746c73]">{cardTitle(note.cardKey)}</p><p className="mt-1 line-clamp-3 text-sm text-[#4d474e]">{note.text}</p></div>) : <p className="px-2 py-8 text-center text-sm text-[#746c73]">No saved notes yet.</p>}</div></div>}</div>
      </div>
    </header>

    <main>
      <section className="relative overflow-hidden border-b border-[#2d2932]/10">
        <div className="mx-auto grid max-w-[1440px] items-center gap-10 px-5 py-14 lg:grid-cols-[0.84fr_1.16fr] lg:px-10 lg:py-20">
          <div className="relative z-10 max-w-[620px]">
            <p className="mb-6 flex items-center gap-2 font-mono text-xs font-bold uppercase tracking-[0.22em] text-[#ff6b6b]"><span className="h-2 w-2 rounded-full bg-[#ff6b6b]" /> The prompt shelf is open</p>
            <h1 className="font-display text-[clamp(3.5rem,7vw,7.2rem)] font-black leading-[0.87] tracking-[-0.065em]">Find the scene<br /><em className="text-[#ff6b6b]">before</em> the words.</h1>
            <p className="mt-8 max-w-[500px] text-lg leading-relaxed text-[#655d66]">A visual library of ready-to-use AI video prompts for stories, lessons, ads, vlogs, and the moments in between. Curated to help you make the next frame feel inevitable.</p>
            <div className="mt-9 flex flex-wrap items-center gap-3"><a href="#library" className="group inline-flex items-center gap-3 rounded-full bg-[#ff6b6b] px-6 py-3.5 text-sm font-bold text-white shadow-[5px_5px_0_#28252a] transition hover:-translate-y-1">Browse the library <ArrowRight size={17} className="transition-transform group-hover:translate-x-1" /></a><span className="font-mono text-xs text-[#746c73]">165 categories · 7 source files</span></div>
          </div>
          <div className="relative min-h-[380px] lg:min-h-[520px]">
            <div className="absolute right-[5%] top-[5%] h-[78%] w-[70%] rotate-3 overflow-hidden rounded-[34px] border-[10px] border-white bg-[#f0d9e5] shadow-[0_22px_60px_rgba(42,34,43,.2)]"><img src={images.hero} alt="Creative director surrounded by storyboards" onError={(event) => { event.currentTarget.onerror = null; event.currentTarget.src = fallbackImage("Prompt Gallery"); }} className="h-full w-full object-cover" /><div className="absolute bottom-4 left-4 rounded-full bg-white/90 px-3 py-1.5 font-mono text-[10px] font-bold uppercase tracking-wider">Visual prompts / 01</div></div>
            <div className="absolute bottom-[5%] left-[4%] w-[42%] -rotate-6 overflow-hidden rounded-[24px] border-[8px] border-white bg-[#d8eefa] shadow-[0_18px_40px_rgba(42,34,43,.18)]"><img src={images.cartoon} alt="3D fox filmmaker" onError={(event) => { event.currentTarget.onerror = null; event.currentTarget.src = fallbackImage("3D Cartoon Stories"); }} className="aspect-[0.95] w-full object-cover" /></div>
            <div className="absolute right-[0%] top-[18%] rounded-2xl bg-[#f8d94e] px-4 py-3 font-mono text-[10px] font-bold uppercase tracking-wider shadow-[4px_4px_0_#28252a]">Copy the spark.<br />Build the story.</div>
            <span className="absolute left-[42%] top-[2%] text-5xl text-[#ff6b6b]">✳</span><span className="absolute bottom-[12%] right-[18%] text-3xl text-[#7ecfbe]">✦</span>
          </div>
        </div>
      </section>

      <section id="complete-library" className="border-b border-[#2d2932]/10 bg-[#fffdf8]"><div className="mx-auto max-w-[1440px] px-5 py-14 lg:px-10 lg:py-20"><div className="mb-9 flex flex-col justify-between gap-5 lg:flex-row lg:items-end"><div><p className="mb-3 font-mono text-xs font-bold uppercase tracking-[0.22em] text-[#ff6b6b]">01 / The complete shelf</p><h2 className="font-display text-5xl font-bold tracking-[-0.05em]">Every word.<br /><span className="text-[#746c73]">Nothing tucked away.</span></h2></div><p className="max-w-md text-sm leading-relaxed text-[#746c73]">The seven original prompt files are now part of the gallery. Open any file to read the exact source text, copy it in full, or download it for your own archive.</p></div><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4">{promptFiles.map((file, index) => <button key={file.id} onClick={() => setSelectedFileId(file.id)} className={`group relative min-h-[178px] overflow-hidden rounded-[24px] border border-[#2d2932]/10 p-5 text-left transition hover:-translate-y-1 hover:shadow-[5px_5px_0_#28252a] ${file.accent === "coral" ? "bg-[#ff6b6b] text-white" : file.accent === "yellow" ? "bg-[#f8d94e]" : file.accent === "lilac" ? "bg-[#b89bd7]" : file.accent === "aqua" ? "bg-[#bce8df]" : file.accent === "peach" ? "bg-[#f4b28e]" : file.accent === "mint" ? "bg-[#a9ddc0]" : "bg-[#f4e9e5]"}`}><span className="flex items-center justify-between font-mono text-[10px] font-bold uppercase tracking-[0.18em] opacity-70"><span>{file.eyebrow}</span><FileText size={15} /></span><span className="mt-9 block max-w-[210px] font-display text-2xl font-bold leading-[0.95] tracking-[-0.03em]">{file.title}</span><span className="mt-4 block text-xs font-semibold opacity-75">Read the exact file <ArrowRight size={13} className="ml-1 inline transition-transform group-hover:translate-x-1" /></span><span className="absolute -bottom-8 -right-5 font-display text-[9rem] font-black leading-none opacity-[0.08]">0{index + 1}</span></button>)}</div></div></section>

      <section id="categories" className="border-b border-[#2d2932]/10 bg-[#fbf7ef]"><div className="mx-auto max-w-[1440px] px-5 py-14 lg:px-10 lg:py-20"><div className="mb-9 flex flex-col justify-between gap-5 lg:flex-row lg:items-end"><div><p className="mb-3 font-mono text-xs font-bold uppercase tracking-[0.22em] text-[#ff6b6b]">02 / The category atlas</p><h2 className="font-display text-5xl font-bold tracking-[-0.05em]">165 ways<br /><span className="text-[#746c73]">to make it move.</span></h2></div><div className="flex w-full max-w-[430px] items-center gap-3 rounded-full border border-[#2d2932]/15 bg-white px-4 py-3 shadow-sm"><Search size={18} className="text-[#746c73]" /><input value={categoryQuery} onChange={(e) => setCategoryQuery(e.target.value)} placeholder="Search all 165 categories..." className="w-full bg-transparent text-sm outline-none placeholder:text-[#9c9398]" /><span className="font-mono text-[10px] text-[#746c73]">{filteredCategories.length}/165</span></div></div><div className="mb-7 flex items-center justify-between"><p className="text-sm text-[#746c73]">Each shelf has its own visual world, format, duration, and ready-made direction.</p><button onClick={() => setCategoryQuery("")} className="font-mono text-[10px] font-bold uppercase tracking-wider text-[#ff6b6b] hover:underline">Show all 165</button></div><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">{visibleCategories.map((category) => <button key={category.id} onClick={() => setSelectedCategory(category)} className="group overflow-hidden rounded-[22px] border border-[#2d2932]/10 bg-white text-left shadow-[0_6px_0_rgba(40,37,42,.045)] transition hover:-translate-y-1 hover:shadow-[0_12px_0_rgba(40,37,42,.09)]"><div className="relative aspect-[1.35] overflow-hidden"><img src={category.image} alt={`${category.title} generated artwork`} loading="lazy" decoding="async" onError={(event) => { event.currentTarget.onerror = null; event.currentTarget.src = fallbackImage(category.title); }} className="h-full w-full object-cover transition duration-500 group-hover:scale-105" /><span className="absolute left-3 top-3 rounded-full bg-white/90 px-2.5 py-1 font-mono text-[9px] font-bold uppercase tracking-wider backdrop-blur">{String(category.id).padStart(3, "0")}</span><span className="absolute bottom-3 right-3 rounded-full bg-[#28252a]/75 px-2.5 py-1 font-mono text-[9px] font-bold uppercase tracking-wider text-white">{category.duration}</span></div><div className="p-4"><div className="mb-2 flex items-center justify-between gap-2"><span className={`h-2 w-2 rounded-full ${category.accent === "coral" ? "bg-[#ff6b6b]" : category.accent === "aqua" ? "bg-[#7ecfbe]" : category.accent === "yellow" ? "bg-[#f8d94e]" : category.accent === "lilac" ? "bg-[#b89bd7]" : category.accent === "peach" ? "bg-[#f4b28e]" : category.accent === "mint" ? "bg-[#83c9a9]" : "bg-[#ec9ab8]"}`} /><span className="font-mono text-[9px] font-bold uppercase tracking-[0.16em] text-[#958c92]">{category.kind} prompt</span></div><h3 className="font-display text-xl font-bold leading-[1] tracking-[-0.03em]">{category.title}</h3><p className="mt-2 line-clamp-2 text-xs leading-relaxed text-[#746c73]">{category.description}</p></div></button>)}</div>{filteredCategories.length > visibleCategoryCount && <div className="mt-8 flex justify-center"><button onClick={() => setVisibleCategoryCount((count) => count + 24)} className="rounded-full border border-[#2d2932]/15 bg-white px-5 py-3 text-sm font-bold shadow-sm transition hover:-translate-y-0.5 hover:border-[#ff6b6b]">Show 24 more · {filteredCategories.length - visibleCategoryCount} remaining</button></div>}{filteredCategories.length === 0 && <div className="rounded-3xl border border-dashed border-[#2d2932]/20 bg-white p-12 text-center"><p className="font-display text-3xl font-bold">No category found.</p><p className="mt-2 text-sm text-[#746c73]">Try “cartoon”, “training”, “vlog”, or “cinematic”.</p></div>}</div></section>

      <section id="library" className="mx-auto max-w-[1440px] px-5 py-14 lg:px-10 lg:py-20">
        <div className="mb-10 flex flex-col justify-between gap-5 lg:flex-row lg:items-end"><div><p className="mb-3 font-mono text-xs font-bold uppercase tracking-[0.22em] text-[#ff6b6b]">03 / Browse the shelf</p><h2 className="font-display text-5xl font-bold tracking-[-0.05em] lg:text-6xl">Pick a feeling.<br /><span className="text-[#746c73]">Then make it move.</span></h2></div><div className="flex w-full max-w-[430px] items-center gap-3 rounded-full border border-[#2d2932]/15 bg-white px-4 py-3 shadow-sm"><Search size={18} className="text-[#746c73]" /><input aria-label="Search prompts, styles, and topics" value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search prompts, styles, topics..." className="w-full bg-transparent text-sm outline-none placeholder:text-[#9c9398]" /><kbd className="hidden rounded-md bg-[#f1ece4] px-2 py-1 font-mono text-[10px] text-[#746c73] sm:block">⌘ K</kbd></div></div>
        <div className="mb-10 flex gap-2 overflow-x-auto pb-2">{categories.map((cat) => <button key={cat.name} onClick={() => setActiveCategory(cat.name)} className={`group flex shrink-0 items-center gap-2 rounded-full border px-4 py-2.5 text-sm font-semibold transition ${activeCategory === cat.name ? "border-[#28252a] bg-[#28252a] text-white" : "border-[#2d2932]/15 bg-white hover:-translate-y-0.5 hover:border-[#ff6b6b]"}`}><span className={`h-2 w-2 rounded-full ${cat.color === "coral" ? "bg-[#ff6b6b]" : cat.color === "lilac" ? "bg-[#b89bd7]" : cat.color === "aqua" ? "bg-[#7ecfbe]" : cat.color === "yellow" ? "bg-[#f8d94e]" : cat.color === "peach" ? "bg-[#f4b28e]" : cat.color === "mint" ? "bg-[#83c9a9]" : cat.color === "rose" ? "bg-[#ec9ab8]" : "bg-[#28252a]"}`} />{cat.name}<span className="font-mono text-[10px] opacity-50">{cat.count}</span></button>)}</div>
        <div className="mb-7 grid gap-4 lg:grid-cols-[1.25fr_.75fr_.75fr]"><button onClick={() => setSelected(prompts[0])} className="group relative min-h-[190px] overflow-hidden rounded-[26px] bg-[#ff6b6b] p-6 text-left text-white shadow-[6px_6px_0_#28252a] transition hover:-translate-y-1"><div className="relative z-10 max-w-[230px]"><span className="font-mono text-[10px] uppercase tracking-[0.2em] text-white/75">Editor’s pick / 01</span><h3 className="mt-8 font-display text-3xl font-bold leading-none">The little fox finds a star</h3><span className="mt-4 inline-flex items-center gap-2 text-xs font-bold">Open prompt <ArrowRight size={14} /></span></div><img src={images.cartoon} alt="" className="absolute -bottom-6 -right-3 h-48 w-48 rounded-full object-cover opacity-90 mix-blend-multiply transition group-hover:scale-105" /></button><button onClick={() => setSelected(prompts[1])} className="group relative min-h-[190px] overflow-hidden rounded-[26px] bg-[#f8d94e] p-6 text-left transition hover:-translate-y-1"><span className="font-mono text-[10px] uppercase tracking-[0.2em] text-[#5f5426]">Mood / rainy</span><h3 className="mt-8 max-w-[180px] font-display text-2xl font-bold leading-none">Make the silence cinematic.</h3><span className="mt-4 inline-flex items-center gap-2 text-xs font-bold">See the scene <ArrowRight size={14} /></span><img src={images.cinematic} alt="" className="absolute -bottom-10 -right-10 h-32 w-32 rounded-full object-cover opacity-80 mix-blend-multiply" /></button><button onClick={() => setSelected(prompts[2])} className="group relative min-h-[190px] overflow-hidden rounded-[26px] bg-[#b89bd7] p-6 text-left transition hover:-translate-y-1"><span className="font-mono text-[10px] uppercase tracking-[0.2em] text-[#4e405c]">Learn / play</span><h3 className="mt-8 max-w-[180px] font-display text-2xl font-bold leading-none">A lesson that keeps moving.</h3><span className="mt-4 inline-flex items-center gap-2 text-xs font-bold">Explore it <ArrowRight size={14} /></span><img src={images.learning} alt="" className="absolute -bottom-8 -right-8 h-36 w-36 rounded-full object-cover opacity-75 mix-blend-multiply" /></button></div><div className="grid gap-5 md:grid-cols-2 xl:grid-cols-3">{filtered.map((p, index) => <article key={p.id} className={`group overflow-hidden rounded-[26px] border border-[#2d2932]/10 bg-white shadow-[0_8px_0_rgba(40,37,42,.05)] transition duration-200 hover:-translate-y-1 hover:shadow-[0_14px_0_rgba(40,37,42,.09)] ${index === 0 ? "md:col-span-2 xl:col-span-1" : ""}`}>
          <button onClick={() => setSelected(p)} className="relative block w-full overflow-hidden text-left"><img src={p.image} alt={`${p.title} AI video prompt artwork`} loading="lazy" decoding="async" onError={(event) => { event.currentTarget.onerror = null; event.currentTarget.src = fallbackImage(p.title); }} className="aspect-[1.25] w-full object-cover transition duration-500 group-hover:scale-105" /><div className="absolute left-4 top-4 rounded-full bg-white/90 px-3 py-1.5 font-mono text-[10px] font-bold uppercase tracking-wider backdrop-blur">{p.category}</div><div className="absolute bottom-4 right-4 grid h-10 w-10 place-items-center rounded-full bg-white/90 text-[#28252a] opacity-0 shadow transition group-hover:opacity-100"><Play size={16} fill="currentColor" /></div></button>
          <div className="p-5"><div className="mb-3 flex items-center justify-between gap-3"><span className="font-mono text-[10px] uppercase tracking-wider text-[#958c92]">{p.type}</span><button onClick={() => toggleSaved(p.id)} aria-label={saved.includes(p.id) ? "Remove from saved" : "Save prompt"} className={`transition hover:scale-110 ${saved.includes(p.id) ? "text-[#ff6b6b]" : "text-[#a39aa0]"}`}><Heart size={18} fill={saved.includes(p.id) ? "currentColor" : "none"} /></button></div><button onClick={() => setSelected(p)} className="text-left"><h3 className="font-display text-2xl font-bold leading-tight tracking-[-0.03em]">{p.title}</h3><p className="mt-2 line-clamp-2 text-sm leading-relaxed text-[#746c73]">{p.excerpt}</p></button><div className="mt-5 flex items-center justify-between border-t border-[#2d2932]/10 pt-4"><span className="flex items-center gap-1.5 font-mono text-[10px] uppercase tracking-wider text-[#746c73]"><Clock3 size={13} /> {p.duration}</span><button onClick={() => copy(p.prompt)} className="inline-flex items-center gap-1.5 rounded-full bg-[#f7f1e8] px-3 py-2 text-xs font-bold transition hover:bg-[#ff6b6b] hover:text-white"><Copy size={13} /> Copy prompt</button></div></div>
        </article>)}</div>
        {filtered.length === 0 && <div className="rounded-3xl border border-dashed border-[#2d2932]/20 bg-white p-16 text-center"><p className="font-display text-3xl font-bold">No prompts in this corner yet.</p><p className="mt-2 text-[#746c73]">Try a different search or category.</p></div>}
      </section>

      <section id="how" className="border-y border-[#2d2932]/10 bg-[#f4e9e5]"><div className="mx-auto grid max-w-[1440px] gap-10 px-5 py-16 lg:grid-cols-[0.8fr_1.2fr] lg:px-10 lg:py-24"><div><p className="mb-3 font-mono text-xs font-bold uppercase tracking-[0.22em] text-[#ff6b6b]">02 / Use it well</p><h2 className="font-display text-5xl font-bold tracking-[-0.05em]">From spark<br />to <em className="text-[#ff6b6b]">sequence.</em></h2><p className="mt-6 max-w-md leading-relaxed text-[#746c73]">The best results come from making continuity explicit. Treat every prompt like a tiny production brief: lock the world, anchor the action, and hand the last frame to the next one.</p><button onClick={() => toast("Studio guide", { description: "Choose a prompt to see its full production brief." })} className="mt-7 inline-flex items-center gap-2 font-bold text-[#ff6b6b]">Read the studio guide <ArrowRight size={16} /></button></div><div className="grid gap-4 sm:grid-cols-3"><div className="rounded-3xl bg-white p-6 shadow-sm"><span className="font-display text-5xl font-bold text-[#ff6b6b]">01</span><h3 className="mt-7 font-display text-xl font-bold">Lock the cast</h3><p className="mt-2 text-sm leading-relaxed text-[#746c73]">Face, height, wardrobe, voice, props. Define once, repeat every scene.</p></div><div className="rounded-3xl bg-[#f8d94e] p-6 shadow-sm"><span className="font-display text-5xl font-bold">02</span><h3 className="mt-7 font-display text-xl font-bold">Name the motion</h3><p className="mt-2 text-sm leading-relaxed text-[#5f5426]">One primary action per clip keeps the story readable and natural.</p></div><div className="rounded-3xl bg-[#b89bd7] p-6 shadow-sm"><span className="font-display text-5xl font-bold">03</span><h3 className="mt-7 font-display text-xl font-bold">Hand off the frame</h3><p className="mt-2 text-sm leading-relaxed text-[#4e405c]">The ending pose of one scene becomes the opening pose of the next.</p></div></div></div></section>

      <section className="mx-auto max-w-[1440px] px-5 py-14 lg:px-10 lg:py-20"><div className="relative overflow-hidden rounded-[32px] bg-[#f4e9e5] px-7 py-10 text-[#28252a] lg:px-14 lg:py-14"><div className="relative z-10 max-w-2xl"><p className="mb-4 font-mono text-xs uppercase tracking-[0.22em] text-[#ff6b6b]">03 / Your next project</p><h2 className="font-display text-4xl font-bold tracking-[-0.04em] lg:text-6xl">Make the prompt<br /><span className="text-[#ff6b6b]">remember for you.</span></h2><p className="mt-5 max-w-lg text-[#746c73]">Choose a category, pick a topic, set the length, and let the Studio build your continuity bible and scene-by-scene plan.</p><button onClick={() => toast("Interactive Studio", { description: "The full prompt builder is ready for the next build." })} className="mt-8 inline-flex items-center gap-2 rounded-full bg-[#ff6b6b] px-6 py-3.5 text-sm font-bold text-white shadow-[4px_4px_0_#28252a] transition hover:-translate-y-1">Open interactive Studio <ArrowRight size={17} /></button></div><div className="absolute -right-10 -top-24 h-80 w-80 rounded-full border-[42px] border-[#ff6b6b]/55" /><div className="absolute -bottom-32 right-40 h-56 w-56 rounded-full border-[28px] border-[#b89bd7]/70" /></div></section>
    </main>

    <footer className="border-t border-[#2d2932]/10 px-5 py-8 lg:px-10"><div className="mx-auto flex max-w-[1440px] flex-col justify-between gap-4 text-sm text-[#746c73] sm:flex-row"><span>© 2026 Prompt Gallery</span><span className="font-mono text-[10px] uppercase tracking-[0.18em]">Made for the next frame</span></div></footer>

    {selectedCategory && <div className="fixed inset-0 z-[70] overflow-y-auto bg-[#28252a]/45 p-4 backdrop-blur-sm sm:p-8" onMouseDown={(e) => { if (e.target === e.currentTarget) setSelectedCategory(null); }}><div className="mx-auto max-w-5xl overflow-hidden rounded-[28px] bg-[#fbf7ef] shadow-2xl"><div className="grid lg:grid-cols-[.78fr_1.22fr]"><div className="relative min-h-[280px] lg:min-h-full"><img src={selectedCategory.image} alt={`${selectedCategory.title} generated artwork`} onError={(event) => { event.currentTarget.onerror = null; event.currentTarget.src = fallbackImage(selectedCategory.title); }} className="absolute inset-0 h-full w-full object-cover" /><div className="absolute inset-0 bg-gradient-to-t from-[#28252a]/70 to-transparent" /><span className="absolute bottom-5 left-5 rounded-full bg-white/90 px-3 py-1.5 font-mono text-[10px] font-bold uppercase tracking-wider">{String(selectedCategory.id).padStart(3, "0")} · {selectedCategory.kind}</span></div><div className="p-6 sm:p-9"><div className="flex items-start justify-between gap-4"><div><p className="font-mono text-[10px] uppercase tracking-[0.18em] text-[#ff6b6b]">Category prompt · {selectedCategory.duration}</p><h2 className="mt-2 font-display text-4xl font-bold leading-none tracking-[-0.05em]">{selectedCategory.title}</h2><p className="mt-4 text-sm leading-relaxed text-[#746c73]">{selectedCategory.description}</p></div><button onClick={() => setSelectedCategory(null)} className="rounded-full bg-white p-2 text-[#746c73] hover:text-[#28252a]" aria-label="Close"><X size={18} /></button></div><div className="mt-6 rounded-2xl border border-[#2d2932]/10 bg-white p-4"><div className="mb-3 flex items-center justify-between"><span className="font-mono text-[10px] font-bold uppercase tracking-wider text-[#ff6b6b]">Full ready-made prompt</span><button onClick={copyCategoryPrompt} className="inline-flex items-center gap-1.5 rounded-full bg-[#ff6b6b] px-3 py-2 text-xs font-bold text-white">{categoryCopied ? <Check size={13} /> : <Copy size={13} />} {categoryCopied ? "Copied" : "Copy prompt"}</button></div><p className="max-h-[52vh] overflow-y-auto whitespace-pre-wrap text-sm leading-relaxed text-[#4d474e]">{selectedCategory.prompt}</p></div><div className="mt-5 rounded-xl bg-[#f4e9e5] px-4 py-3 text-xs leading-relaxed text-[#746c73]">Use the image above as the visual direction for this category. The prompt is designed for connected 10-second scenes and includes character, environment, camera, audio, and continuity controls.</div><CardNotes notes={activeCardKey === `category-${selectedCategory.id}` ? activeNotes : []} draft={comment} editingId={editingNoteId} onDraftChange={setComment} onSubmit={addOrUpdateNote} onEdit={editNote} onDelete={deleteNote} onCancel={cancelEditNote} /></div></div></div></div>}

    {selectedFile && selectedFileId && <div role="dialog" aria-modal="true" aria-label="Complete prompt source file" className="fixed inset-0 z-[60] overflow-y-auto bg-[#28252a]/45 p-4 backdrop-blur-sm sm:p-8" onMouseDown={(e) => { if (e.target === e.currentTarget) setSelectedFileId(null); }}><div className="mx-auto max-w-5xl overflow-hidden rounded-[28px] bg-[#fbf7ef] shadow-2xl"><div className="flex flex-col gap-5 border-b border-[#2d2932]/10 p-6 sm:flex-row sm:items-center sm:justify-between sm:p-8"><div><p className="font-mono text-[10px] uppercase tracking-[0.18em] text-[#ff6b6b]">Exact source file · {selectedFile.eyebrow}</p><h2 className="mt-2 font-display text-4xl font-bold tracking-[-0.05em]">{selectedFile.title}</h2><p className="mt-2 text-sm text-[#746c73]">{selectedFile.description}</p></div><div className="flex shrink-0 items-center gap-2"><button onClick={copyFullFile} className="inline-flex items-center gap-2 rounded-full bg-[#ff6b6b] px-4 py-2.5 text-xs font-bold text-white shadow-[3px_3px_0_#28252a]">{fileCopied ? <Check size={14} /> : <Copy size={14} />} {fileCopied ? "Copied" : "Copy full file"}</button><a href={`data:text/markdown;charset=utf-8,${encodeURIComponent(fileContents[selectedFileId] || "")}`} download={selectedFile.filename} className="inline-flex items-center gap-2 rounded-full border border-[#2d2932]/15 bg-white px-4 py-2.5 text-xs font-bold"><Download size={14} /> Download</a><button onClick={() => setSelectedFileId(null)} className="rounded-full bg-white p-2 text-[#746c73] hover:text-[#28252a]" aria-label="Close"><X size={18} /></button></div></div><div className="max-h-[68vh] overflow-y-auto bg-white p-6 sm:p-10"><pre className="whitespace-pre-wrap break-words font-mono text-[12px] leading-[1.75] text-[#4d474e]">{fileContents[selectedFileId] || "Loading the exact source text…"}</pre></div></div></div>}

    {selected && <div role="dialog" aria-modal="true" aria-label={selected ? `${selected.title} prompt details` : "Prompt details"} className="fixed inset-0 z-50 overflow-y-auto bg-[#28252a]/45 p-4 backdrop-blur-sm sm:p-8" onMouseDown={(e) => { if (e.target === e.currentTarget) setSelected(null); }}><div className="mx-auto max-w-4xl overflow-hidden rounded-[28px] bg-[#fbf7ef] shadow-2xl"><div className="grid lg:grid-cols-[.8fr_1.2fr]"><div className="relative min-h-[260px] lg:min-h-full"><img src={selected.image} alt={`${selected.title} AI video prompt artwork`} onError={(event) => { event.currentTarget.onerror = null; event.currentTarget.src = fallbackImage(selected.title); }} className="absolute inset-0 h-full w-full object-cover" /><div className="absolute inset-0 bg-gradient-to-t from-[#28252a]/60 to-transparent" /><span className="absolute bottom-5 left-5 rounded-full bg-white/90 px-3 py-1.5 font-mono text-[10px] font-bold uppercase tracking-wider">{selected.category}</span></div><div className="p-6 sm:p-9"><div className="flex items-start justify-between gap-4"><div><p className="font-mono text-[10px] uppercase tracking-wider text-[#ff6b6b]">{selected.type} · {selected.duration}</p><h2 className="mt-2 font-display text-4xl font-bold leading-none tracking-[-0.05em]">{selected.title}</h2></div><button onClick={() => setSelected(null)} className="rounded-full bg-white p-2 text-[#746c73] hover:text-[#28252a]" aria-label="Close"><X size={18} /></button></div><p className="mt-5 text-sm leading-relaxed text-[#746c73]">{selected.excerpt}</p><div className="mt-6 rounded-2xl border border-[#2d2932]/10 bg-white p-4"><div className="mb-3 flex items-center justify-between"><span className="font-mono text-[10px] font-bold uppercase tracking-wider text-[#ff6b6b]">Full production prompt</span><button onClick={() => copy(selected.prompt)} className="inline-flex items-center gap-1.5 rounded-full bg-[#ff6b6b] px-3 py-2 text-xs font-bold text-white"><Copy size={13} /> Copy</button></div><p className="max-h-64 overflow-y-auto whitespace-pre-wrap text-sm leading-relaxed text-[#4d474e]">{selected.prompt}</p></div><CardNotes notes={activeCardKey === `prompt-${selected.id}` ? activeNotes : []} draft={comment} editingId={editingNoteId} onDraftChange={setComment} onSubmit={addOrUpdateNote} onEdit={editNote} onDelete={deleteNote} onCancel={cancelEditNote} /></div></div></div></div>}
  </div>;
}
